<?php
 namespace Pterodactyl\Services\Dezerx\ServerCreate; use Throwable; use Pterodactyl\Models\User; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Http; use Pterodactyl\Models\Dezerx\DiscordLink; class Discord { private const AUTHORISE = 'https://discord.com/oauth2/authorize'; private const API = 'https://discord.com/api/v10'; public const SCOPES = 'identify guilds.join'; private const TIMEOUT = 10; public static function clientId(): string { return trim((string) ServerCreate::setting('discord_client_id')); } public static function clientSecret(): string { return trim((string) ServerCreate::setting('discord_client_secret')); } public static function botToken(): string { return trim((string) ServerCreate::setting('discord_bot_token')); } public static function guildId(): string { return trim((string) ServerCreate::setting('discord_guild_id')); } public static function configured(): bool { return self::clientId() !== '' && self::clientSecret() !== ''; } public static function required(): bool { return ServerCreate::flag('discord_required') && self::configured(); } public static function joins(): bool { return self::botToken() !== '' && self::guildId() !== ''; } public static function linkFor(User $user): ?DiscordLink { return DiscordLink::query()->where('user_id', $user->id)->first(); } public static function linked(User $user): bool { return self::linkFor($user) !== null; } public static function takenByAnother(string $discordId, User $user): bool { return DiscordLink::query() ->where('discord_id', $discordId) ->where('user_id', '!=', $user->id) ->exists(); } public static function unlink(User $user): void { DiscordLink::query()->where('user_id', $user->id)->delete(); } public static function consentUrl(string $redirect, string $state): string { return self::AUTHORISE . '?' . http_build_query([ 'client_id' => self::clientId(), 'redirect_uri' => $redirect, 'response_type' => 'code', 'scope' => self::SCOPES, 'state' => $state, 'prompt' => 'consent', ]); } public static function exchange(string $code, string $redirect): ?array { try { $response = Http::asForm() ->timeout(self::TIMEOUT) ->post(self::API . '/oauth2/token', [ 'client_id' => self::clientId(), 'client_secret' => self::clientSecret(), 'grant_type' => 'authorization_code', 'code' => $code, 'redirect_uri' => $redirect, ]); } catch (Throwable $exception) { Log::warning('discord: token exchange failed', ['error' => $exception->getMessage()]); return null; } if (!$response->successful() || !is_string($response->json('access_token'))) { Log::warning('discord: token exchange refused', ['status' => $response->status()]); return null; } return $response->json(); } public static function identity(string $accessToken): ?array { try { $response = Http::withToken($accessToken)->timeout(self::TIMEOUT)->get(self::API . '/users/@me'); } catch (Throwable $exception) { Log::warning('discord: identity lookup failed', ['error' => $exception->getMessage()]); return null; } if (!$response->successful() || !is_string($response->json('id'))) { return null; } $body = $response->json(); return [ 'id' => (string) $body['id'], 'username' => (string) ($body['global_name'] ?? $body['username'] ?? 'Unknown'), 'avatar' => is_string($body['avatar'] ?? null) ? $body['avatar'] : null, ]; } public static function joinGuild(string $discordId, string $accessToken): bool { if (!self::joins()) { return false; } try { $response = Http::withHeaders(['Authorization' => 'Bot ' . self::botToken()]) ->timeout(self::TIMEOUT) ->put(self::API . '/guilds/' . self::guildId() . '/members/' . $discordId, [ 'access_token' => $accessToken, ]); } catch (Throwable $exception) { Log::warning('discord: guild join failed', ['error' => $exception->getMessage()]); return false; } if (!$response->successful()) { Log::warning('discord: guild join refused', [ 'status' => $response->status(), 'body' => mb_substr($response->body(), 0, 200), ]); return false; } return true; } } 